// Live link to the Group 6 challenge data in ../gate-sorting-algorithm.
// Add a scenario JSON to flight_data/ and it appears in the dashboard.
import staticJson from "../../../gate-sorting-algorithm/static_info.json";
import type { Scenario, StaticInfo } from "../engine/model";

export const staticInfo = staticJson as StaticInfo;

const repoFiles = import.meta.glob<Scenario>("../../../gate-sorting-algorithm/flight_data/*.json", {
  eager: true,
  import: "default",
});
// Extra stress-test days generated by scripts/make_scenarios.py (kept out of the challenge data folder).
const extraFiles = import.meta.glob<Scenario>("../../scenarios/*.json", { eager: true, import: "default" });
const files = { ...repoFiles, ...extraFiles };

const LABELS: Record<string, string> = {
  busy_day: "Busy day",
  rush_hour: "Rush hour + outage",
  emergencies: "Emergency diversions",
  gate_outage: "Gate outage",
  equipment_upgrade: "Equipment upgrade",
  cascade_1: "Delay cascade 1",
  cascade_2: "Delay cascade 2",
  cancel: "Cancellation",
  cargo: "Cargo",
  domestic_787: "Domestic 787",
  overnight: "Overnight",
  simple: "Simple",
  super_busy: "Super busy day",
  overload_crunch: "Overload crunch",
  storm_day: "Storm day",
};

/**
 * Each scenario is placed on the calendar relative to today: earlier days are
 * completed history, today is live, later days are planned schedules.
 * Scenarios not listed here are added after the last planned day.
 */
const DAY_OFFSETS: Record<string, number> = {
  simple: -7,
  cargo: -6,
  cancel: -5,
  cascade_1: -4,
  cascade_2: -3,
  domestic_787: -2,
  overnight: -1,
  rush_hour: 0,
  busy_day: 1,
  emergencies: 2,
  gate_outage: 3,
  equipment_upgrade: 4,
  super_busy: 5,
  overload_crunch: 6,
  storm_day: 7,
};

export type DayKind = "history" | "today" | "planned";

export type ScenarioEntry = { id: string; label: string; data: Scenario; date: Date; kind: DayKind };

const startOfToday = () => {
  const d = new Date();
  d.setHours(0, 0, 0, 0);
  return d;
};

let nextExtra = Math.max(...Object.values(DAY_OFFSETS)) + 1;

export const scenarios: ScenarioEntry[] = Object.entries(files)
  .map(([path, data]) => {
    const id = path.split("/").pop()!.replace(".json", "");
    const offset = DAY_OFFSETS[id] ?? nextExtra++;
    const date = startOfToday();
    date.setDate(date.getDate() + offset);
    const kind: DayKind = offset < 0 ? "history" : offset === 0 ? "today" : "planned";
    return { id, label: LABELS[id] ?? id.replace(/_/g, " "), data, date, kind };
  })
  .sort((a, b) => a.date.getTime() - b.date.getTime());

export const sameDay = (a: Date, b: Date) => a.toDateString() === b.toDateString();

